  if (opts.bodyTooLarge) return { ok: false, error: `must be at most ${MAX_BODY_BYTES} bytes` };
  const mediaType = opts.contentType?.split(';')[0]?.trim().toLowerCase();
  if (mediaType !== 'application/json') return { ok: false, error: 'Content-Type must be application/json' };
  let parsed: unknown;
  try {
    parsed = JSON.parse(opts.body);
  } catch {
    return { ok: false, error: 'must be valid JSON' };
  }
  if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
    return { ok: false, error: 'must be a JSON object' };
  }
  return { ok: true, value: parsed as Record<string, unknown> };
}

