import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase } from './db.ts';
import {
  claimNextJob,
  clearHeartbeat,
  completeJob,
  failJob,
  HEARTBEAT_EVERY_MS,
  MAX_ATTEMPTS,
  recoverExpiredJobs,
  releaseJob,
  renewProgress,
  scheduleRetry,
  STEP_MS,
  writeHeartbeat,
  type JobRow,
} from './jobs.ts';

const IDLE_POLL_MS = 200;

const db = openDatabase();
let stopping = false;

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

/** Runs one attempt. `job.attempts` already counts this attempt. */
async function processJob(job: JobRow): Promise<void> {
  if (job.attempts <= job.fail_attempts) {
    // Simulated transient failure, before any progress.
    if (job.attempts < MAX_ATTEMPTS) scheduleRetry(db, job.id, Date.now());
    else failJob(db, job.id, Date.now());
    return;
  }

  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    if (stopping) {
      // Shutting down mid-job: hand the job back so another worker or the next start can resume it.
      releaseJob(db, job.id, Date.now());
      return;
    }
    renewProgress(db, job.id, step, Date.now());
  }
  completeJob(db, job.id, job.input.toUpperCase(), Date.now());
}

writeHeartbeat(db, Date.now());
const heartbeat = setInterval(() => writeHeartbeat(db, Date.now()), HEARTBEAT_EVERY_MS);

console.log('worker started');
while (!stopping) {
  recoverExpiredJobs(db, Date.now());
  const job = claimNextJob(db, Date.now());
  if (!job) {
    await sleep(IDLE_POLL_MS);
    continue;
  }
  await processJob(job);
}

clearInterval(heartbeat);
clearHeartbeat(db);
db.close();
console.log('worker stopped');

